def cross_product(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def on_segment(p, a, b):
    return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

def segments_intersect(a, b, c, d):
    d1 = cross_product(b, c, d)
    d2 = cross_product(b, d, c)
    d3 = cross_product(c, d, b)
    d4 = cross_product(c, b, d)
    if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
        return True
    if d1 == 0 and on_segment(c, a, b):
        return True
    if d2 == 0 and on_segment(c, b, c):
        return True
    if d3 == 0 and on_segment(d, a, b):
        return True
    if d4 == 0 and on_segment(b, c, d):
        return True
    return False

def point_in_triangle(c, a, b, d):
    return cross_product(a, c, b) * cross_product(b, c, d) >= 0 and \
           cross_product(c, a, d) * cross_product(d, c, b) >= 0

def is_disjoint(t1, t2, points):
    a, b, c = t1
    d, e, f = t2

    # Check vertex containment
    if any(p_in_tri == 1 for p_in_tri in [point_in_triangle(a, d, e, f),
                                           point_in_triangle(b, d, e, f),
                                           point_in_triangle(c, d, e, f),
                                           point_in_triangle(d, a, b, c),
                                           point_in_triangle(e, a, b, c),
                                           point_in_triangle(f, a, b, c)]):
        return False

    # Check edge intersections
    for i, j in [(a, b), (b, c), (c, a)]:
        for k, l in [(d, e), (e, f), (f, d)]:
            if segments_intersect(i, j, k, l):
                return False

    return True

def generate_triangles(points):
    triangles = []
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            for k in range(j + 1, len(points)):
                triangles.append((points[i], points[j], points[k]))
    return triangles

def count_disjoint_triangles(n, points):
    triangles = generate_triangles(points)
    count = 0
    m = len(triangles)
    for i in range(m):
        for j in range(i + 1, m):
            if is_disjoint(triangles[i], triangles[j], points):
                count += 1
    return count

