    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            count = 0
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(count)

    # Generate lucky numbers up to n
    lucky = [4, 7, 44, 47, 74, 77, 444, 447, 474, 477, 744, 747, 774, 777]
    candidates = set([lucky])

    queue = [4, 7]
    while queue:
        curr = queue.pop(0)
        if curr <= n:
            candidates.add(curr)
            queue.extend([curr * 10 + 4, curr * 10 + 7]) if curr * 10 + 4 <= n else None
            queue.extend([curr * 10 + 7]) if curr * 10 + 7 <= n else None

    lucky = sorted(candidates)

    if n == 0:
        return "-1\n"

    # DP: dp[s] = minimum number of components to achieve sum s
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for size in components:
        for j in range(n, size - 1, -1):
            if dp[j - size] != float('inf'):
                dp[j] = min(dp[j], dp[j - size] + 1)

    # Find the minimum roads needed for each lucky number
    min_roads = float('inf')
    for L in lucky:
        if dp[L] < float('inf'):
            min_roads = min(min_roads, dp[L] - 1)

    if min_roads == float('inf'):
