                while temp % p == 0:
                    temp //= p
                    count += 1
                # Store based on index parity
                if idx % 2 == 1:
                    odd_factors[p] = odd_factors.get(p, 0) + count
                else:
                    even_factors[p] = even_factors.get(p, 0) + count
            p += 1
        if temp > 1:
            # Remaining prime factor
            if idx % 2 == 1:
                odd_factors[temp] = odd_factors.get(temp, 0) + 1
            else:
                even_factors[temp] = even_factors.get(temp, 0) + 1

    # Calculate maximum operations
    total_ops = 0
    all_primes = set(odd_factors.keys()) | set(even_factors.keys())

    for p in all_primes:
        total_ops += min(odd_factors.get(p, 0), even_factors.get(p, 0))

