    if len(greedy_indep) >= target:
        sorted_indep = sorted(list(greedy_indep))
        return "1\n" + " ".join(map(str, sorted_indep[:target]))

    # Final fallback: try BFS layer independent set properly
    visited_bfs2 = [False] * (n + 1)
    layer_nodes_list = []

    bfs_queue = [1]
    visited_bfs2[1] = True
    current_level = [1]
    next_level = []

    while bfs_queue:
        for u in current_level:
            for v in adj[u]:
                if not visited_bfs2[v]:
