            right_blocked = False
            # icicles at position >= current_pos (indices current_pos-1 to n-1)
            for i in range(current_pos - 1, n):
                if fall_times[i] <= t:
                    right_blocked = True
                    break

            if right_blocked:
                min_time = min(min_time, t)

