def solve_original(n, l, r, a, b):
    """
    Solve the actual problem using dynamic programming.

    We want to maximize the number of important boxes whose bottom edge
    is in the range [l, r] when we stack boxes from height 0.

    DP approach:
    - dp[h] = maximum convenience achievable with total height exactly h
    - We process each box and decide where to place it
    - When we place an important box at height h (where h is the height
      before adding this box, i.e., the box's bottom edge), if l <= h <= r,
      we get +1 convenience.
    """
    import sys

    total_sum = sum(a)
    dp = [-float('inf')] * (total_sum + 1)
    dp[0] = 0

    for i in range(n):
        height = a[i]
        important = b[i]

        for h in range(total_sum, -1, -1):
            if dp[h] == -float('inf'):
                continue

            new_h = h + height
            if new_h <= total_sum:
                # Evaluate if placing this box at height h gives convenience
                gain = 1 if (important == 1 and l <= h <= r) else 0
                dp[new_h] = max(dp[new_h], dp[h] + gain)

    return max(dp)


