    # Memoization cache for f_r(p^k)
    cache = {}

    def get_fr_pk(r, k):
        """Returns f_r(p^k) for any prime p"""
        if k == 0:
            return 1
        if r == 0:
            return 2
        if (r, k) in cache:
            return cache[(r, k)]

