        # fr(p^k) = sum_{j=0}^k fr-1(p^j)
        # Note: f0(1) = 1, f0(p^k) = 2 for k >= 1

        result = 0
        for j in range(k + 1):
            val = get_fr_pk(r - 1, j)
            result = (result + val) % MOD

        cache[(r, k)] = result
        return result

