    # R = N + M + (8*intersecting + 3*touching + 2) // 5
    R = N + M + (8 * intersecting + 3 * touching + 2) // 5

    return str(R)

def solution(input_str):
    n, k = map(int, input_str.split())
    MOD = 998244353

    if k == 1:
        return str(n) + '\n'

    if k > n:
        return '0\n'

    # Precompute all divisors for 1 to n
    divisors = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(i, n + 1, i):
            divisors[j].append(i)

    # dp[i] = number of valid chains of current length ending at position i
    # For length 1, each position forms a valid chain (just itself)
    dp = [1] * (n + 1)

    # Build chains of increasing length
    for length in range(2, k + 1):
        new_dp = [0] * (n + 1)
        for i in range(1, n + 1):
            for d in divisors[i]:
                new_dp[i] = (new_dp[i] + dp[d]) % MOD
        dp = new_dp

    # Sum all chains of length k ending at any valid position
    ans = sum(dp[1:]) % MOD
    return str(ans) + '\n'

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, k = int(lines[0].split()[0]), int(lines[0].split()[1])
    a = list(map(int, lines[1].split()))

    # Check initial array
    for x in a:
        if x >= k:
            return '0\n'

    # Simulate iterations using binomial coefficient formula
    # A[i][n-1] = sum_{j=0}^{n-1} C(i+j, j) * a[j]
    i = 1
    while True:
        val = 0
        current_binom = 1  # C(i+0, 0) = 1
        for j in range(n):
            val += current_binom * a[j]
            # Update binom: C(i+j+1, j+1) = C(i+j, j) * (i+j+1)/(j+1)
            if j < n - 1:
                current_binom = current_binom * (i + j + 1) // (j + 1)

        if val >= k:
            return f'{i}\n'

        i += 1
